    const applied=SI_CLASS_FIELDS.filter(function(field){return siClassApplied[field[0]].length;}).map(function(field){return field[1]+'：'+siClassApplied[field[0]].map(function(value){return value==='—'?'未设置':value;}).join('、');}).join('；')||'全部在校班级';
