  function siClassReadDraft(){const root=document.getElementById('siClassFilters');if(!root)return;SI_CLASS_FIELDS.forEach(function(field){const node=root.querySelector('[data-si-class-field="'+field[0]+'"]');siClassDraft[field[0]]=[...node.querySelectorAll('input[type=checkbox]:checked')].map(function(input){return input.value;});});}
  function siClassFiltersInit(){
    const root=document.getElementById('siClassFilters');if(!root)return;let groups=siClassGroups(dashboardScopedStudents(viewFilter.dashboard||{}));
    SI_CLASS_FIELDS.forEach(function(field){const key=field[0],allowed=new Set(groups.map(function(group){return group[key];}));siClassDraft[key]=siClassDraft[key].filter(function(value){return allowed.has(value);});const node=root.querySelector('[data-si-class-field="'+key+'"]');node.querySelector('.qf-multi-trigger').setAttribute('aria-labelledby','siClassLabel_'+key);node.querySelectorAll('input[type=checkbox]').forEach(function(input){const valid=allowed.has(input.value);input.disabled=!valid;input.checked=siClassDraft[key].includes(input.value);input.closest('.qf-multi-opt').style.display=valid?'':'none';});qfMultiRefresh(node);const search=node.querySelector('.sf-search-input');if(search)search.dispatchEvent(new Event('input',{bubbles:true}));if(siClassDraft[key].length)groups=groups.filter(function(group){return siClassDraft[key].includes(group[key]);});});
  }
