    const meta=siClassMeta(),rows=siClassStudents(snapshot.students).filter(function(student){const facts=siClassFacts(student,meta);return (all||(facts.dept===siText(dept)&&facts.major===siText(major)&&facts.grade===siText(grade)&&facts.cls===siText(cls)))&&siClassMemberMatches(student,type);}).sort(function(a,b){return siText(a.id).localeCompare(siText(b.id));});
