      +'<article class="sc-panel sc-risk-panel"><div class="sc-panel-head"><span class="sc-panel-title">重点处置概览</span><span class="sc-panel-note">点击进入业务模块</span></div><div class="sc-panel-body sc-risk-grid">'+riskCard("红色重点学生",snapshot.risk.red,snapshot.risk.red?"建议优先人工核查":"当前无红色重点", "var(--sc-red)","portrait")+riskCard("橙色关注学生",snapshot.risk.orange,snapshot.risk.orange?"建议近期跟进":"当前无橙色关注","var(--sc-orange)","portrait")+riskCard("处分尚未解除",snapshot.activePunish.length,snapshot.activePunish.length?"按当前权限范围":"当前无未解除处分","var(--sc-purple)","punishment")+riskCard("档案待完善",snapshot.quality.incompleteStudents,snapshot.quality.incompleteStudents?"基础字段缺失":"基础档案完整","var(--sc-yellow)","student")+'</div></article>'
